export const token=new URLSearchParams(location.search).get('convite')||'';
export const personal=path=>{const u=new URL(path,location.origin);if(token)u.searchParams.set('convite',token);return u.pathname+u.search};
export async function api(path,{method='GET',body}={}){const headers={};if(body!==undefined)headers['Content-Type']='application/json';if(token&&!path.startsWith('/api/admin/'))headers['X-Invite-Token']=token;const res=await fetch(path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});let data;try{data=await res.json()}catch{throw new Error('O serviço ainda não está disponível.')}if(!res.ok)throw Object.assign(new Error(data.error||'Não foi possível concluir.'),{status:res.status});return data}
export function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
export function button(text,fn,cls=''){const b=el('button',text,cls);b.type='button';b.onclick=async()=>{b.disabled=true;try{await fn()}catch(e){await message(e.message)}finally{b.disabled=false}};return b}
export function message(text){return new Promise(resolve=>{const d=document.createElement('dialog');d.append(el('p',text));const b=button('Fechar',()=>d.close());d.append(b);d.addEventListener('close',()=>{d.remove();resolve()},{once:true});document.body.append(d);d.showModal()})}
export function confirmAction(text){return new Promise(resolve=>{const d=document.createElement('dialog');d.append(el('p',text));const actions=el('div',undefined,'actions');actions.append(button('Cancelar',()=>d.close('no'),'secondary'),button('Confirmar',()=>d.close('yes')));d.append(actions);d.addEventListener('close',()=>{const yes=d.returnValue==='yes';d.remove();resolve(yes)},{once:true});document.body.append(d);d.showModal()})}
